import React, { useEffect, useRef, useState } from 'react';

export default function LocationSection() {
  const [visible, setVisible] = useState(false);
  const ref = useRef();

  useEffect(() => {
    const obs = new IntersectionObserver(([e]) => {
      if (e.isIntersecting) setVisible(true);
    }, { threshold: 0.1 });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);

  const openMaps = () => {
    window.open('https://maps.app.goo.gl/F1n6ThNggwHMEpZK7', '_blank');
  };

  return (
    <section ref={ref} style={{
      background: 'linear-gradient(180deg, #fff 0%, #fce8f5 100%)',
      padding: '80px 20px 120px',
      textAlign: 'center',
    }}>
      <style>{`
        @keyframes fadeUp2 {
          from { opacity: 0; transform: translateY(30px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .map-btn:hover {
          background: linear-gradient(135deg, #c91578, #a01060) !important;
          transform: translateY(-2px) !important;
          box-shadow: 0 8px 25px rgba(233,30,140,0.4) !important;
        }
        .map-container {
          border-radius: 16px;
          overflow: hidden;
          box-shadow: 0 8px 30px rgba(0,0,0,0.12);
          border: 3px solid #f0d0e8;
        }
      `}</style>

      {/* Title */}
      <h2 style={{
        fontFamily: "'Dancing Script', cursive",
        fontSize: 'clamp(1.8rem, 5vw, 2.8rem)',
        color: '#e91e8c',
        marginBottom: '30px',
        opacity: visible ? 1 : 0,
        animation: visible ? 'fadeUp2 0.7s ease 0.1s forwards' : 'none',
      }}>
        Lokasi Akad &amp; Resepsi Pernikahan
      </h2>

      {/* Open Maps button */}
      <button
        className="map-btn"
        onClick={openMaps}
        style={{
          background: 'linear-gradient(135deg, #e91e8c, #c91578)',
          color: 'white',
          border: 'none',
          borderRadius: '50px',
          padding: '14px 36px',
          fontSize: '0.9rem',
          fontWeight: 600,
          fontFamily: "'Poppins', sans-serif",
          cursor: 'pointer',
          letterSpacing: '0.08em',
          display: 'inline-flex',
          alignItems: 'center',
          gap: '10px',
          marginBottom: '36px',
          transition: 'all 0.2s',
          boxShadow: '0 4px 15px rgba(233,30,140,0.3)',
          opacity: visible ? 1 : 0,
          animation: visible ? 'fadeUp2 0.7s ease 0.2s forwards' : 'none',
        }}
      >
        📍 BUKA DI GOOGLE MAPS
      </button>

      {/* Map embed */}
      <div
        className="map-container"
        style={{
          maxWidth: '780px',
          margin: '0 auto',
          opacity: visible ? 1 : 0,
          animation: visible ? 'fadeUp2 0.8s ease 0.3s forwards' : 'none',
        }}
      >
        <iframe
          title="Lokasi Pernikahan - Karangduren"
          src=""
          width="100%"
          height="420"
          style={{ border: 0, display: 'block' }}
          allowFullScreen=""
          loading="lazy"
          referrerPolicy="no-referrer-when-downgrade"
        />
      </div>
    </section>
  );
}
